local _, addon = ...

addon.localeData.frFR.texts = {
 MARK={name="Marque du fauve",ziel={"Que la nature veille sur vous, %s.","Que racines, vent et étoiles vous fortifient, %s.","*lève une main vers %s tandis qu'un souffle léger tourbillonne autour de la cible.*"},gruppe={"Que la nature veille sur nous.","Que la nature nous accorde force et endurance."}},
 GIFT={name="Don du fauve",gruppe={"Que la bénédiction de la nature soit sur vous tous.","De nombreuses branches, un seul être vivant.","*écarte les mains tandis que la bénédiction se répand sur le groupe.*"}},
 THORNS={name="Épines",ziel={"Que les épines vous protègent, %s.","Que chaque coup porté contre vous ait son prix, %s.","*trace un geste protecteur autour de %s tandis que des épines spectrales apparaissent.*"},gruppe={"La nature n'est pas sans défense.","Qui nous frappe rencontre les épines."}},
 REJUVENATION={name="Récupération",ziel={"Qu'une force nouvelle grandisse en vous, %s.","Laissez la nature apaiser vos blessures, %s.","*pose une main lumineuse près des blessures de %s tandis que la vie renaît.*"},gruppe={"À chaque souffle, la force revient.","La vie revient peu à peu."}},
 REGROWTH={name="Rétablissement",ziel={"Comme les jeunes pousses après l'orage, relevez-vous plus fort, %s.","Que la nature referme vos blessures, %s.","*guide une poussée de vie verdoyante vers %s.*"},gruppe={"Même après l'orage, la forêt repousse.","Là où demeure la vie, la guérison peut croître."}},
 HEALING_TOUCH={name="Toucher guérisseur",ziel={"Que la force de la terre vous guérisse, %s.","Restez avec nous, %s. La nature vous prête sa force.","*pose une main ferme sur %s et canalise la puissance paisible de la nature.*"},gruppe={"La nature nous accorde la guérison.","La vie trouve toujours son chemin."}},
 TRANQUILITY={name="Tranquillité",gruppe={"Faites silence et écoutez respirer la forêt.","Que le tumulte du combat s'apaise un instant.","*lève les mains tandis qu'une douce lueur verte enveloppe les compagnons.*"}},
 INNERVATE={name="Innervation",ziel={"Puisez profondément dans le courant de la vie, %s.","Que la nature renouvelle votre esprit, %s.","*attire vers %s une nouvelle vague de puissance naturelle.*"},gruppe={"Le courant de la vie n'est pas tari.","Des sources silencieuses naît une force nouvelle."}},
 REBIRTH={name="Renaissance",ziel={"Revenez parmi nous, %s. Votre route n'est pas terminée.","La vie vous appelle par votre nom, %s.","*s'agenouille auprès de %s et appelle le cycle de la vie à tourner encore une fois.*"},gruppe={"Le cycle nous accorde une nouvelle chance.","La vie rappelle un compagnon."}},
 NATURES_GRASP={name="Emprise de la nature",gruppe={"La nature attend le prochain pas imprudent.","Approchez. La terre est prête.","Qui s'approche trop sentira les racines répondre.","La nature saisit ceux qui me menacent.","Le sol sous mes pieds est plus éveillé qu'il n'y paraît.","Un pas de trop, et la nature retiendra sa proie.","*abaisse une main vers le sol tandis que de fines racines frémissent sous la terre.*","*trace un geste dans l'air; des lianes cachées répondent sous ses pieds.*"}},
 ROOTS={name="Sarments",ziel={"Racines de la terre, retenez %s !","Pas un pas de plus, %s. Le sol lui-même vous retient.","*frappe la terre d'un geste et des racines jaillissent autour de %s.*"},gruppe={"Racines de la terre, retenez-les !","Là où les racines saisissent, la charge s'arrête."}},
 MOONFIRE={name="Éclat lunaire",ziel={"La lumière de la lune vous trouve, %s.","Que le feu d'argent brûle sur vous, %s.","*désigne %s tandis qu'un trait de froide lumière lunaire s'abat.*"},gruppe={"Le feu d'argent perce les ténèbres.","La lune répond à mon appel."}},
 WRATH={name="Colère",gruppe={"La nature élève la voix.","Le vent et la terre répondent à mon appel.","*rassemble la force de la nature en une décharge brutale.*"}},
 BARKSKIN={name="Écorce",gruppe={"Comme une vieille écorce, je tiens face à la tempête.","Aujourd'hui, je ne romps pas.","*affermit sa posture tandis qu'une écorce rugueuse couvre la peau.*"}},
 BEAR={name="Forme d'ours",gruppe={"Avec la force de l'ours, je protège mes compagnons.","Griffes prêtes. Je tiens la ligne.","*prend la forme puissante d'un ours dans un grondement sourd.*"}},
 CAT={name="Forme de félin",gruppe={"Des pas silencieux et des sens aiguisés me guident.","Les griffes n'ont pas besoin de longs discours.","*se fond dans une forme féline et adopte une posture de chasse silencieuse.*"}},
 TRAVEL={name="Forme de voyage",gruppe={"Le vent me montre la voie.","Là où un chemin s'arrête, un autre commence.","*prend une forme de voyage rapide et s'élance.*"}},
 AQUATIC={name="Forme aquatique",gruppe={"Le courant me porte.","Sous la surface attend une autre nature sauvage.","*prend une forme aquatique et glisse dans l'eau.*"}},
 MOONKIN={name="Forme de sélénien",gruppe={"Sous la lune et les étoiles, je garde l'équilibre.","Les étoiles sont lointaines. Leur puissance ne l'est pas.","*prend la forme d'un sélénien dans un éclat de lumière astrale.*"}},
 TREE={name="Arbre de vie",gruppe={"Mes racines tiennent, mes branches apportent la guérison.","Approchez. Il reste de la place sous mes branches.","*s'enracine tandis que la forme de l'Arbre de vie apparaît.*"}},
 FLIGHT={name="Forme de vol",gruppe={"Le ciel m'ouvre ses chemins.","Le sol peut attendre. Le ciel m'appelle.","*déploie ses ailes et s'élève dans le ciel ouvert.*"}},
    -- Dialogues druidiques distincts pour les formes et les sorts
    STARFIRE = { name = "Feu stellaire", gruppe = { "Même l'étoile lointaine traverse les feuilles et les ombres.", "Une étincelle céleste suffit pour déchirer la nuit.", "*trace la course d'une étoile entre ses mains levées.*", "*lève les yeux au-dessus des arbres et appelle un rayon argenté.*" }, ziel = { "%s, même le ciel lointain t'a retrouvé." }, },
    INSECT_SWARM = { name = "Essaim d'insectes", gruppe = { "Les plus petites créatures de la nature livrent leurs propres batailles.", "Le bourdonnement devient menace lorsque la forêt s'éveille.", "*effleure une fleur et libère un nuage d'ailes du sous-bois.*", "*guide d'une main une multitude de petites ailes.*" }, ziel = { "%s, ne sous-estime pas ces petites ailes." }, },
    HURRICANE = { name = "Ouragan", gruppe = { "Le vent ne demandera pas la permission.", "La cime des arbres annonçait déjà la tempête.", "*décrit de grands cercles des bras jusqu'à faire hurler l'air.*", "*prend appui tandis que les feuilles dansent dans la bourrasque.*" }, },
    FAERIE_FIRE = { name = "Lucioles", gruppe = { "Que les ombres cachées apparaissent dans la lumière de la clairière.", "L'étincelle féerique révèle le pas le plus discret.", "*dessine une feuille lumineuse dans l'air.*", "*laisse une traînée scintillante sur le sentier.*" }, ziel = { "Te cacher ne servira à rien, %s." }, },
    FAERIE_FIRE_FERAL = { name = "Lucioles farouches", gruppe = { "Même les griffes parlent le langage des fées.", "La forêt marque ses ennemis d'une autre lumière.", "*secoue une étrange lueur de sa fourrure.*", "*trace une ligne brillante dans la terre avec ses griffes.*" }, ziel = { "Tu es marqué, %s. La forêt te voit." }, },
    ECLIPSE = { name = "Éclipse", gruppe = { "Le soleil et la lune ne se disputent pas. Ils partagent le ciel.", "Quand une lumière s'efface, l'autre naît.", "*rapproche les paumes alors qu'un cercle de lumière s'assombrit.*", "*baisse la tête comme si une ombre traversait le soleil.*" }, },
    WILD_GROWTH = { name = "Croissance sauvage", gruppe = { "Une racine nourrit rarement une seule branche.", "Grandissez là où la bataille a blessé la terre.", "*envoie une onde verte dans les rangs des compagnons.*", "*touche le sol et répand un cercle de jeunes feuilles.*" }, },
    BLOOM = { name = "Floraison", gruppe = { "La plus petite graine peut devenir un printemps.", "Une fleur n'a besoin de personne pour offrir l'espoir.", "*ouvre les mains comme si un bouton invisible éclatait.*", "*répand le parfum des pétales frais dans l'air.*" }, ziel = { "La nature fleurit pour toi, %s." }, },
    PRIMAL_BITE = { name = "Morsure primordiale", gruppe = { "La nature ne s'excuse jamais de sa faim.", "Une morsure suffit à décider de la chasse.", "*tend les épaules comme un prédateur prêt à bondir.*", "*claque les mâchoires dans une ouverture de la garde ennemie.*" }, ziel = { "%s, tu connais maintenant les crocs sauvages." }, },
    LACERATE = { name = "Lacérer", gruppe = { "Toutes les entailles ne guérissent pas avec une feuille.", "Les traces des griffes demeurent après la bataille.", "*prend une position basse et porte des coups déchirants.*", "*passe les griffes devant soi en un arc violent.*" }, ziel = { "Tu te souviendras de cette plaie, %s." }, },
    REVIVE = { name = "Ranimer", gruppe = { "Parfois la vie sommeille derrière une porte fermée.", "Reviens. Les racines et les voix t'attendent encore.", "*s'agenouille et pose la main sur un cœur silencieux.*", "*parle doucement à un compagnon tombé tandis que la lumière verdit.*" }, ziel = { "%s, la nature t'appelle à revenir." }, },
    SWIFTMEND = { name = "Prompte guérison", gruppe = { "La nature prend le chemin le plus court quand le danger presse.", "Un instant de chaleur verte peut suffire.", "*projette une étincelle de guérison concentrée.*", "*cueille une lueur curative dans l'air et la pose sur une blessure.*" }, ziel = { "Tiens bon, %s. Cela ira mieux." }, },
    NATURES_SWIFTNESS = { name = "Rapidité de la nature", gruppe = { "Quand la nature décide, elle n'hésite pas.", "Le vent n'attend jamais une deuxième pensée.", "*se redresse brusquement comme parcouru par une brise.*", "*touche la terre et se concentre en un souffle.*" }, },
    OMEN_OF_CLARITY = { name = "Augure de clarté", gruppe = { "La réponse se cache entre deux respirations.", "Le choix le plus juste grandit dans le silence.", "*ferme les yeux et écoute une voix intérieure.*", "*laisse une faible lueur courir sur les doigts.*" }, },
    SOOTHE_ANIMAL = { name = "Apaiser un animal", gruppe = { "Doucement, petit cœur. Nous ne sommes pas obligés de combattre.", "On ne vainc pas la peur avec des dents.", "*abaisse les épaules et parle calmement à l'animal.*", "*garde la main ouverte et attend un signe de confiance.*" }, ziel = { "Du calme, %s. Je ne veux rien te prendre." }, },
    HIBERNATE = { name = "Hibernation", gruppe = { "Un profond sommeil vaut parfois mieux qu'un combat.", "Le silence hivernal ne connaît pas la hâte.", "*dessine un cercle paisible et baisse la voix.*", "*souffle un peu de givre et de calme dans les fourrés.*" }, ziel = { "Dors, %s. La nuit sera assez longue." }, },
    REMOVE_CURSE = { name = "Délivrance de la malédiction", gruppe = { "Aucun mot obscur ne doit enchaîner ce cœur.", "Une malédiction est une histoire dont je change la fin.", "*efface un nœud invisible du bout des doigts.*", "*retire une ombre de l'épaule d'un compagnon.*" }, ziel = { "%s, cette malédiction ne t'appartient plus." }, },
    CURE_POISON = { name = "Guérison du poison", gruppe = { "Pour chaque venin, la terre cultive une réponse patiente.", "La bonne racine l'emporte sur la mauvaise piqûre.", "*écrase une feuille guérisseuse entre les doigts.*", "*pose une main chaude et verte au-dessus d'une blessure.*" }, ziel = { "%s, laisse la nature reprendre ce poison." }, },
    ABOLISH_POISON = { name = "Abolir le poison", gruppe = { "Que plus aucune goutte de venin ne vole tes forces.", "Je garde ce souffle de son ennemi silencieux.", "*retire une trace sombre de l'air avec des doigts sûrs.*", "*murmure un vieux vers de guérison alors que la lueur augmente.*" }, ziel = { "%s, ce poison n'a plus de refuge." }, },
    POUNCE = { name = "Traquenard", gruppe = { "L'ombre bondit avant même que la branche ne bouge.", "Un atterrissage silencieux gagne la moitié de la chasse.", "*se tapit puis jaillit de sa cachette.*", "*atterrit griffes sorties, tout près du sol.*" }, ziel = { "Tu m'as vu trop tard, %s." }, },
    SHRED = { name = "Lambeau", gruppe = { "Toute défense laisse une ouverture. Mes griffes la connaissent.", "Le coup le plus discret est celui qu'on n'attend pas.", "*contourne le flanc et déchire de toutes ses forces.*", "*profite du mouvement adverse pour frapper par derrière.*" }, ziel = { "Protège ton dos, %s." }, },
    RAKE = { name = "Griffure", gruppe = { "Une petite entaille laisse un long souvenir.", "Les griffes écrivent plus vite que les mots.", "*trace trois lignes rapides dans l'air.*", "*bondit de côté et frappe d'un coup de patte.*" }, ziel = { "Souviens-toi de cet avertissement, %s." }, },
    RIP = { name = "Déchirure", gruppe = { "La chasse est désormais décidée.", "Le prédateur n'oublie jamais sa dernière chance.", "*s'engage dans une attaque profonde et décisive.*", "*s'élance du sol et porte un coup de griffes déchirant.*" }, ziel = { "La chasse se termine ici, %s." }, },
    FEROCIOUS_BITE = { name = "Morsure féroce", gruppe = { "Le prédateur réserve ses forces pour la morsure finale.", "Les crocs ne menacent pas. Ils promettent.", "*contracte la mâchoire et bondit de près.*", "*projette le corps en avant et mord d'un geste fulgurant.*" }, ziel = { "Il n'y a plus de place, %s." }, },
    CLAW = { name = "Griffe", gruppe = { "De petites cicatrices racontent de longues batailles.", "La patte est rapide, la griffe décidée.", "*déchire l'air d'un coup de patte rapide.*", "*se baisse puis porte une griffure nette.*" }, ziel = { "Ne méprise pas les petites griffes, %s." }, },
    MAUL = { name = "Mutiler", gruppe = { "L'ours ne demande jamais si l'arbre paraît solide.", "Parfois la nature répond par sa force brute.", "*se redresse sur ses puissantes épaules et frappe vers le bas.*", "*abat ses lourdes pattes de toute sa force.*" }, ziel = { "Voici la réponse de l'ours, %s." }, },
    SWIPE = { name = "Balayage", gruppe = { "Un seul coup disperse plusieurs ombres.", "La forêt frappe large lorsqu'elle se défend.", "*balaie un grand arc d'une patte massive.*", "*déchire l'air d'un mouvement puissant.*" }, },
    BASH = { name = "Sonner", gruppe = { "L'immobilité est parfois la réponse la plus douce.", "Un coup lourd épargne mille paroles.", "*se redresse et porte un coup bref mais puissant.*", "*frappe avec la patte et tient sa position.*" }, ziel = { "Un peu de calme, %s." }, },
    GROWL = { name = "Grondement", gruppe = { "Voici mon territoire. Mes amis se tiennent derrière moi.", "Un grondement explique souvent assez.", "*se place devant le groupe et grogne profondément.*", "*montre les crocs pour détourner l'attention des autres.*" }, ziel = { "Par ici, %s. Je t'attends." }, },
    ENRAGE = { name = "Enrager", gruppe = { "Même la forêt paisible connaît les tempêtes.", "La patience ne se termine pas toujours doucement.", "*enfonce ses griffes dans le sol et tend tous ses muscles.*", "*pousse un long grondement sourd.*" }, },
    DASH = { name = "Célérité", gruppe = { "Le chemin raccourcit lorsqu'on le parcourt sur quatre pattes.", "Le vent dans les poils, la terre sous les griffes.", "*s'élance avant qu'une feuille ne touche le sol.*", "*se faufile entre les arbres à toute vitesse.*" }, },
    PROWL = { name = "Rôder", gruppe = { "Une feuille bruisse. Pas moi.", "Seule la nature sait où je marche.", "*se glisse dans l'herbe et disparaît dans l'ombre.*", "*avance sans casser la moindre brindille.*" }, },
    FRENZIED_REGENERATION = { name = "Régénération frénétique", gruppe = { "Un ours ne tombe pas parce que la vie devient difficile.", "La terre rend ce que le combat a pris.", "*respire fortement puis redresse son immense silhouette.*", "*plante les pattes et rassemble les dernières forces.*" }, },
    CHALLENGING_ROAR = { name = "Rugissement provocateur", gruppe = { "Si vous cherchez le combat, regardez-moi !", "Mes compagnons resteront derrière mes épaules.", "*pousse un rugissement tonitruant à travers la clairière.*", "*frappe le sol de sa patte et barre la route.*" }, },
    FERAL_CHARGE = { name = "Charge farouche", gruppe = { "Aucun obstacle n'arrête un ours décidé.", "D'abord la terre tremble. Ensuite j'arrive.", "*prend appui sur ses pattes arrière et charge.*", "*lance son épaule dans une brèche soudaine.*" }, ziel = { "J'arrive, %s." }, },
    DEMORALIZING_ROAR = { name = "Rugissement démoralisant", gruppe = { "Le courage ne ressemble pas à ce grognement.", "Même une forêt pleine d'ennemis peut se taire.", "*lève la tête et pousse un rugissement grave.*", "*hérisse le poil et remplit la clairière de son cri.*" }, },
    SHAPE_SHIFT = { name = "Métamorphose", gruppe = { "La peau n'est qu'une forme de la vie.", "Je porte plusieurs formes mais une seule mémoire.", "*baisse la tête tandis que le corps se fond dans une lueur verte.*", "*ramène les mains à la poitrine tandis qu'une nouvelle forme apparaît.*" }, },
    REJUVENATING_BLOOM = { name = "Floraison régénératrice", gruppe = { "La plus petite fleur connaît le chemin de la vie.", "Une pousse entre les pierres suffit pour promettre le printemps.", "*fait éclore un bouton entre ses doigts.*", "*répand une tendre lueur verte sur une plaie.*" }, ziel = { "%s, la nature offre un nouveau départ." }, },
}
